1	export const runScenario = (scenario: unknown): { results: unknown[] } => {
2	  return { results: [{ premium: 5 }] };
3	};
4

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest / edge ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	    expect(result.results[0]).toEqual({ premium: 5 });
12	  });
13	
14	  // --- Quote: single main items (base + always-on first insurance + fee) ---
15	  it.todo("single plain sword (base 100) → newcomer premium 115 G (100 + 10 first insurance + 5 fee)");
16	  it.todo("single plain amulet (base 60) → newcomer premium 71 G (60 + 6 + 5)");
17	  it.todo("single plain staff (base 80) → newcomer premium 93 G (80 + 8 + 5)");
18	  it.todo("single plain potion (base 40) → newcomer premium 49 G (40 + 4 + 5)");
19	
20	  // --- Quote: component building blocks ---
21	  it.todo("2 runes → base premium 50 G (no block)");
22	  it.todo("3 runes → base premium 60 G (block of exactly 3 applies)");
23	  it.todo("4 runes → base premium 100 G (no block — block requires exactly 3)");
24	  it.todo("7 runes → base premium 175 G (one block of 3 + 4 singles)");
25	
26	  // --- Quote: "alike" components ---
27	  it.todo("2 runes + 1 moonstone → base premium 75 G (no block: different types)");
28	  it.todo("3 runes + 3 moonstones → base premium 120 G (two separate blocks)");
29	
30	  // --- Quote: item-level modifiers in isolation ---
31	  it.todo("cursed sword adds 50% of the item base premium (curse surcharge = 50 G)");
32	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (30 G)");
33	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
34	  it.todo("cursed sword with enchantment 5 → both curse and high-enchantment surcharges apply");
35	
36	  // --- Quote: policy-level modifiers ---
37	  it.todo("customer with exactly 2 years with MHPCO → 20% loyalty discount applies");
38	  it.todo("customer with 1 year → no loyalty discount");
39	  it.todo("second quote in a scenario → 15% follow-up contract discount applies");
40	  it.todo("first insurance surcharge (10%) applies to every item regardless of customer history");
41	
42	  // --- Quote: modifier scope on multi-item policies ---
43	  it.todo("cursed sword (base 100) + plain amulet (base 60) → policy base 160, curse adds 50 (of sword base) → 210 before loyalty/follow-up/fee");
44	
45	  // --- Quote: rounding ---
46	  it.todo("premium calculation yielding 197.5 G → final premium 198 G (rounded up, MHPCO favor)");
47	
48	  // --- Quote: integration examples ---
49	  it.todo("newcomer with a cursed sword (steel, ench 3) → premium 165 G");
50	  it.todo("long-standing customer's second contract, cursed sword (steel, ench 7) → premium 160 G");
51	
52	  // --- Claim: standard reimbursement ---
53	  it.todo("regular sword (steel, ench 3), damage 500 → payout 400 G (full minus 100 deductible)");
54	  it.todo("damage to a rune (value 250), damage 200 → payout 100 G (full minus 100 deductible, no special clause)");
55	
56	  // --- Claim: special clauses ---
57	  it.todo("dragon-material sword, ench 5, damage 800 → payout 700 G (dragon full reimbursement, then deductible)");
58	  it.todo("steel sword, ench 9, damage 1000 → payout 400 G (high-enchantment 50% first, then deductible)");
59	  it.todo("dragon-material sword, ench 9, damage 1000 → payout 400 G (both clauses; 50% wins, then deductible)");
60	  it.todo("dragon-material sword, exactly ench 8, damage 1000 → payout 400 G (high-enchantment clause, then deductible)");
61	
62	  // --- Claim: deductible per damage event ---
63	  it.todo("dragon attack damaging insured sword (500) and amulet (300) → payout 600 G (deductible once per damaged item)");
64	
65	  // --- Claim: rounding ---
66	  it.todo("payout calculation yielding 350.5 G → final payout 350 G (rounded down, MHPCO favor)");
67	
68	  // --- Claim: insurance sum & cap ---
69	  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
70	  it.todo("cursed sword → cap 2000 G (based on unmodified insurance value; premium modifiers do not raise the cap)");
71	  it.todo("policy covering a sword and 3 runes (block) → insurance sum 1750 G (block discount affects premium only)");
72	
73	  // --- Claim: multiple items of the same type ---
74	  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
75	  it.todo("dragon attack damaging both swords (two sword entries) → each treated as separate damage with its own deductible");
76	
77	  // --- Claim: cap exhaustion across successive claims ---
78	  it.todo("sword (cap 2000), first claim 1500 → payout 1400 G, remaining cap 600 G");
79	  it.todo("sword (cap 2000), two successive 1500 claims → second payout 600 G, remaining cap 0 G (reduced to remaining cap)");
80	
81	  // --- Errors (CLI exits non-zero) ---
82	  it.todo("quote with an unknown item type (e.g. broomstick) → error (no results produced)");
83	  it.todo("claim referencing an item not part of the policy → error");
84	  it.todo("claim with more damage entries of a type than the policy covers → error");
85	  it.todo("claim with a negative damage amount → error");
86	
87	  // --- CLI schema example (end-to-end shape) ---
88	  it.todo("schema example: amulet quote then amulet claim → results [{premium}, {payout, remainingCap}]");
89	});
